Here is the commit message:
bpf: sk_msg, fix socket data_ready events

When a skb verdict program is in-use and either another BPF program
redirects to that socket or the new SK_PASS support is used the
data_ready callback does not wake up application. Instead because
the stream parser/verdict is using the sk data_ready callback we wake
up the stream parser/verdict block.

Fix this by adding a helper to check if the stream parser block is
enabled on the sk and if so call the saved pointer which is the
upper layers wake up function.

This fixes application stalls observed when an application is waiting
for data in a blocking read().

Fixes: d829e9c4112b ("tls: convert to generic sk_msg interface")
Signed-off-by: John Fastabend <john.fastabend@gmail.com>
Signed-off-by: Daniel Borkmann <daniel@iogearbox.net>

Here is the root cause:
The bug occurs because when a socket is involved with a stream parser and a skb verdict program is in use, the data_ready callback does not wake up the application as expected. Instead, it incorrectly wakes up the stream parser/verdict block, leading to application stalls during blocking read operations. This happens because the original data_ready function is not called when the stream parser is enabled, causing the application to remain blocked and unable to receive data.

Here is the patch:

 static int sk_psock_skb_ingress(struct sk_psock *psock, struct sk_buff *skb)
 {
 	struct sock *sk = psock->sk;
 	int copied = 0, num_sge;
 	struct sk_msg *msg;

 	msg = kzalloc(sizeof(*msg), __GFP_NOWARN | GFP_ATOMIC);
 	if (unlikely(!msg))
 		return -EAGAIN;
 	if (!sk_rmem_schedule(sk, skb, skb->len)) {
 		kfree(msg);
 		return -EAGAIN;
 	}

 	sk_msg_init(msg);
 	num_sge = skb_to_sgvec(skb, msg->sg.data, 0, skb->len);
 	if (unlikely(num_sge < 0)) {
 		kfree(msg);
 		return num_sge;
 	}

 	sk_mem_charge(sk, skb->len);
 	copied = skb->len;
 	msg->sg.start = 0;
 	msg->sg.end = num_sge == MAX_MSG_FRAGS ? 0 : num_sge;
 	msg->skb = skb;

 	sk_psock_queue_msg(psock, msg);
-	sk->sk_data_ready(sk);
+	sk_psock_data_ready(sk, psock);
 	return copied;
 }

 /* Called with socket lock held. */
-static void sk_psock_data_ready(struct sock *sk)
+static void sk_psock_strp_data_ready(struct sock *sk)
 {
 	struct sk_psock *psock;

 	rcu_read_lock();
 	psock = sk_psock(sk);
 	if (likely(psock)) {
 		write_lock_bh(&sk->sk_callback_lock);
 		strp_data_ready(&psock->parser.strp);
 		write_unlock_bh(&sk->sk_callback_lock);
 	}
 	rcu_read_unlock();
 }


 void sk_psock_start_strp(struct sock *sk, struct sk_psock *psock)
 {
 	struct sk_psock_parser *parser = &psock->parser;

 	if (parser->enabled)
 		return;

 	parser->saved_data_ready = sk->sk_data_ready;
-	sk->sk_data_ready = sk_psock_data_ready;
+	sk->sk_data_ready = sk_psock_strp_data_ready;
 	sk->sk_write_space = sk_psock_write_space;
 	parser->enabled = true;
 }



